contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry executing the property check
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 payAmount
    ) public payable {
        // ensure we have enough balance to forward ETH if needed
        if (payAmount > 0) {
            require(address(this).balance >= payAmount, "test lacks ETH");
        }

        // read pre-state observable values
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        address nftAddr = c.nft();

        // prepare MerkleMultiProof struct for calldata
        C.MerkleMultiProof memory mp;
        mp.proof = proofProof;
        mp.flags = proofFlags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // call buy; must be a top-level statement
        try c.buy{value: payAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // post-state observable values
        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();

        // Check ownership of each token: if buy succeeded, caller (this contract) should NOT own them; they should have been transferred to external msg.sender of buy (which in this test is address(this) because InvMutTest calls c). Since the test contract is the caller, after buy succeeds the NFTs should belong to address(this).
        // We read ownerOf via ERC721 ownerOf public function on the NFT contract.
        bool allTransferred = true;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            // try/catch to handle NOT_MINTED reverts — if revert, treat as not transferred
            try ERC721(nftAddr).ownerOf(tokenIds[i]) returns (address owner) {
                if (owner != address(this)) allTransferred = false;
            } catch {
                allTransferred = false;
            }
        }

        // General invariant asserted:
        // Either the buy call reverted, or if it succeeded then:
        // - virtualNftReserves decreased by exactly the sum of tokenWeights (observable: postVirtualNft <= preVirtualNft and difference equals sum)
        // - virtualBaseTokenReserves increased by at least netInputAmount - feeAmount - protocolFeeAmount minus royalties (we can't observe royalties directly), so we assert it increased by >= 0 and by at most netInputAmount+protocolFeeAmount+feeAmount to avoid underflow/overflow
        // - all NFTs are owned by the caller (this contract)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Compose the assertion: either reverted, or all conditions hold
        assert(
            reverted || (
                // post virtual NFT reserves decreased by exactly sumWeights (note both are uint128; cast to uint256 for safe comparison)
                uint256(preVirtualNft) >= uint256(postVirtualNft) && uint256(preVirtualNft) - uint256(postVirtualNft) == sumWeights
                // virtual base reserves did not decrease (should increase or stay same)
                && uint256(postVirtualBase) >= uint256(preVirtualBase)
                // caller received the NFTs
                && allTransferred
            )
        );
    }

    receive() external payable {}
}

