contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry executing the property check
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags,
        uint256 payAmount
    ) public payable {
        // allow forwarding ETH
        if (payAmount > 0) {
            require(address(this).balance >= payAmount, "insufficient test ETH");
        }

        // Observe pre-state
        uint128 preVirtualNft = c.virtualNftReserves();
        address nftAddr = c.nft();
        uint256 len = tokenIds.length;

        // prepare MerkleMultiProof struct (memory)
        C.MerkleMultiProof memory mp;
        mp.proof = proofProof;
        mp.flags = proofFlags;

        // Perform the state-changing call as a top-level statement and capture revert
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: payAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint128 postVirtualNft = c.virtualNftReserves();

        // Compute sum of weights locally
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Count how many of the specified tokenIds are still owned by the pool
        uint256 stillOwnedByPool = 0;
        for (uint256 i = 0; i < len; i++) {
            // If ownerOf reverts treat as not owned by pool
            try ERC721(nftAddr).ownerOf(tokenIds[i]) returns (address owner) {
                if (owner == address(c)) stillOwnedByPool++;
            } catch {
                // consider as not owned by pool
            }
        }

        // General property:
        // Either the buy reverted, or it succeeded and (1) virtualNftReserves decreased by exactly sumWeights,
        // and (2) the pool no longer owns all of the specified tokenIds (i.e., at least len NFTs were transferred out).
        assert(
            reverted || (
                uint256(preVirtualNft) >= uint256(postVirtualNft)
                && uint256(preVirtualNft) - uint256(postVirtualNft) == sumWeights
                && stillOwnedByPool < len
            )
        );
    }

    receive() external payable {}
}

