                && uint256(postVirtualBase) >= uint256(preVirtualBase)
                && uint256(postVirtualBase) - uint256(preVirtualBase) >= (netInputAmount >= feeAmount + protocolFeeAmount ? netInputAmount - feeAmount - protocolFeeAmount : 0)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Only one public function as required
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags
    ) public payable {
        // require some simple bounds so the checker can reason: arrays non-empty and same length
        require(tokenIds.length == tokenWeights.length && tokenIds.length > 0, "bad input lengths");
        // Prepare MerkleMultiProof in memory
        C.MerkleMultiProof memory mp;
        mp.proof = proofProof;
        mp.flags = proofFlags;

        // Observe pre-state
        uint128 before = c.virtualNftReserves();

        // Call sell and capture whether it reverted and returned values
        bool reverted;
        uint256 netOutputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.sell(tokenIds, tokenWeights, mp, new C.IStolenNftOracle.Message[](0)) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netOutputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint128 after = c.virtualNftReserves();

        // compute sum of weights
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Assert the invariant: if sell succeeded (did not revert) then virtualNftReserves increased by exactly sumWeights
        assert(reverted || uint256(after) == uint256(before) + sumWeights);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will test deposit(uint256[] calldata tokenIds, uint256 baseTokenAmount)
    // Params: tokenIds array length up to arbitrary; supply baseTokenAmount and an explicit sendEthAmount
    // If baseToken == address(0) then deposit expects msg.value == baseTokenAmount, otherwise msg.value must be 0.
    // The rule: after calling deposit (or reverted), either the call reverted exactly when the msg.value vs baseToken mismatch condition holds,
    // or the call succeeded and for ETH pools address(c).balance increased by baseTokenAmount and initialized flag is unchanged (still whatever it was before).

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 sendEthAmount) public payable {
        require(address(this).balance >= sendEthAmount, "insufficient balance to forward");

        // Observe pre-call initialized and baseToken and pool balance
        bool beforeInitialized = c.initialized();
        address poolBaseToken = c.baseToken();
        uint256 beforePoolEthBalance = address(c).balance;

        bool reverted;
        // Perform the deposit: send ETH equal to sendEthAmount (may be zero)
        try c.deposit{value: sendEthAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterInitialized = c.initialized();
        uint256 afterPoolEthBalance = address(c).balance;

        // If the pool uses ETH (baseToken == address(0)) then deposit requires msg.value == baseTokenAmount
        // If the pool uses ERC20 (baseToken != address(0)) then deposit requires msg.value == 0
        // Our general rule: the call reverts iff the msg.value vs baseToken mismatch condition holds OR other external conditions;
        // but we can assert a necessary condition: if call succeeded then initialized unchanged AND
        // for ETH pools the pool ETH balance increased by exactly baseTokenAmount and for ERC20 pools the pool ETH balance did not change.

        assert(
            // assert that initialization state never changes as a result of deposit (deposit shouldn't flip initialized)
            (afterInitialized == beforeInitialized)
            &&
            (
                // If call reverted, we don't assert anything further about balances (just accept revert). However we must still reach assert.
                reverted
                ||
                (
                    // call succeeded: now enforce ETH-balance observable invariants
                    (
                        // ETH pool: baseToken == address(0) -> c balance increased by baseTokenAmount
                        poolBaseToken == address(0) && afterPoolEthBalance == beforePoolEthBalance + baseTokenAmount
                    )
                    ||
                    (
                        // ERC20 pool: baseToken != address(0) -> c ETH balance unchanged
                        poolBaseToken != address(0) && afterPoolEthBalance == beforePoolEthBalance
                    )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single-call property test for setFeeRate(uint16 newFeeRate)
    // Param: newFeeRate must fit uint16 (always true for uint16 param)
    function run(uint16 newFeeRate) public payable {
        // Observe before value
        uint16 before = c.feeRate();

        bool reverted;
        // Call setFeeRate; it requires onlyOwner, but in the test environment InvMutTest is the deployer of c
        // The call may revert if newFeeRate > 5000 per contract logic or if caller is not owner.
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint16 after = c.feeRate();

        // General rule: if the call did NOT revert then feeRate() must equal the requested newFeeRate;
        // if it reverted then feeRate() must be unchanged from before.
        assert(
            (!reverted && after == newFeeRate) || (reverted && after == before)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single-call property test for setFeeRate(uint16 newFeeRate)
    // The test caller is the owner of the pool (Factory ownerOf uses the token id = uint160(address(c)) and
    // the checker deploys a fresh C whose owner is this contract), so onlyOwner should permit the call.
    function run(uint16 newFeeRate) public payable {
        // Read feeRate before the call
        uint16 beforeFeeRate = c.feeRate();

        bool reverted;
        // top-level state-changing call (may revert)
        try c.setFeeRate(newFeeRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read feeRate after the call
        uint16 afterFeeRate = c.feeRate();

        // General property:
        // If the call reverted, feeRate must be unchanged. If it did not revert, feeRate must equal the requested value.
        // Additionally, the contract logic limits feeRate to <= 5000; encode that relation in the assertion.
        assert(
            (reverted && afterFeeRate == beforeFeeRate) ||
            (!reverted && afterFeeRate == newFeeRate && newFeeRate <= 5000)
        );
    }

    receive() external payable {}
}
